import{_ as e,o,c as i,a1 as d}from"./chunks/framework.DdbKPUhY.js";const f=JSON.parse('{"title":"Config API Spec","description":"","frontmatter":{},"headers":[],"relativePath":"spec/config-api.md","filePath":"spec/config-api.md"}'),n={name:"spec/config-api.md"};function a(r,t,s,l,c,u){return o(),i("div",null,[...t[0]||(t[0]=[d('<h1 id="config-api-spec" tabindex="-1">Config API Spec <a class="header-anchor" href="#config-api-spec" aria-label="Permalink to &quot;Config API Spec&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Config module provides server configuration options. Configuration is set at the server level and can be shared across multiple server instances.</p><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;Interfaces&quot;">​</a></h2><h3 id="uvhttp-config-new" tabindex="-1">uvhttp_config_new <a class="header-anchor" href="#uvhttp-config-new" aria-label="Permalink to &quot;uvhttp_config_new&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_config_new(uvhttp_config_t** config)</code></li><li><strong>Purpose</strong>: Create a new config object with default values</li><li><strong>Preconditions</strong>: <code>config</code> must be non-NULL.</li><li><strong>Postconditions</strong>: On success, <code>*config</code> points to a config with all default values.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: config is NULL</li><li><code>UVHTTP_ERROR_OUT_OF_MEMORY</code>: allocation failure</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-config-free" tabindex="-1">uvhttp_config_free <a class="header-anchor" href="#uvhttp-config-free" aria-label="Permalink to &quot;uvhttp_config_free&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>void uvhttp_config_free(uvhttp_config_t* config)</code></li><li><strong>Purpose</strong>: Free a config object</li><li><strong>Preconditions</strong>: <code>config</code> can be NULL (no-op).</li><li><strong>Postconditions</strong>: All memory is freed.</li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-config-set-defaults" tabindex="-1">uvhttp_config_set_defaults <a class="header-anchor" href="#uvhttp-config-set-defaults" aria-label="Permalink to &quot;uvhttp_config_set_defaults&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>void uvhttp_config_set_defaults(uvhttp_config_t* config)</code></li><li><strong>Purpose</strong>: Reset config to default values</li><li><strong>Preconditions</strong>: <code>config</code> must be valid.</li><li><strong>Postconditions</strong>: All config fields are set to their default values.</li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-config-validate" tabindex="-1">uvhttp_config_validate <a class="header-anchor" href="#uvhttp-config-validate" aria-label="Permalink to &quot;uvhttp_config_validate&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>int uvhttp_config_validate(const uvhttp_config_t* config)</code></li><li><strong>Purpose</strong>: Validate config values against min/max bounds</li><li><strong>Preconditions</strong>: <code>config</code> must be valid.</li><li><strong>Returns</strong>: 0 if valid, non-zero (error code) if invalid.</li><li><strong>Thread safety</strong>: Thread-safe for reads.</li></ul><h3 id="uvhttp-config-get-current-uvhttp-config-set-current" tabindex="-1">uvhttp_config_get_current / uvhttp_config_set_current <a class="header-anchor" href="#uvhttp-config-get-current-uvhttp-config-set-current" aria-label="Permalink to &quot;uvhttp_config_get_current / uvhttp_config_set_current&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_config_t* uvhttp_config_get_current(uvhttp_context_t* context)</code> / <code>void uvhttp_config_set_current(uvhttp_context_t* context, uvhttp_config_t* config)</code></li><li><strong>Purpose</strong>: Get/set the current config on a context</li><li><strong>Preconditions</strong>: <code>context</code> must be valid.</li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h2 id="configurable-options" tabindex="-1">Configurable Options <a class="header-anchor" href="#configurable-options" aria-label="Permalink to &quot;Configurable Options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Default</th><th>Range</th><th>Description</th></tr></thead><tbody><tr><td><code>max_connections</code></td><td>size_t</td><td>2048</td><td>1-65535</td><td>Max concurrent connections</td></tr><tr><td><code>keepalive_timeout</code></td><td>int</td><td>60</td><td>0-3600</td><td>Keep-alive timeout (seconds)</td></tr><tr><td><code>request_timeout</code></td><td>int</td><td>30</td><td>1-3600</td><td>Request timeout (seconds)</td></tr><tr><td><code>max_header_size</code></td><td>size_t</td><td>8192</td><td>256-65536</td><td>Max header size (bytes)</td></tr><tr><td><code>max_body_size</code></td><td>size_t</td><td>10485760</td><td>1024-1073741824</td><td>Max body size (bytes)</td></tr><tr><td><code>max_headers</code></td><td>int</td><td>64</td><td>8-256</td><td>Max header count</td></tr><tr><td><code>read_buffer_size</code></td><td>size_t</td><td>4096</td><td>256-65536</td><td>Read buffer size (bytes)</td></tr><tr><td><code>backlog</code></td><td>int</td><td>128</td><td>0-65535</td><td>TCP listen backlog</td></tr><tr><td><code>tcp_nodelay</code></td><td>int</td><td>1</td><td>0-1</td><td>TCP_NODELAY</td></tr><tr><td><code>tcp_keepalive</code></td><td>int</td><td>1</td><td>0-1</td><td>TCP keepalive</td></tr><tr><td><code>websocket_max_frame_size</code></td><td>size_t</td><td>65536</td><td>1024-1048576</td><td>Max WebSocket frame (bytes)</td></tr><tr><td><code>websocket_ping_interval</code></td><td>int</td><td>30</td><td>5-300</td><td>Ping interval (seconds)</td></tr><tr><td><code>websocket_ping_timeout</code></td><td>int</td><td>10</td><td>3-60</td><td>Ping timeout (seconds)</td></tr></tbody></table><h2 id="behavior-rules" tabindex="-1">Behavior Rules <a class="header-anchor" href="#behavior-rules" aria-label="Permalink to &quot;Behavior Rules&quot;">​</a></h2><ol><li><p><strong>Defaults</strong>: All fields have sensible defaults. Callers can create a config and only change the fields they need.</p></li><li><p><strong>Validation</strong>: <code>uvhttp_config_validate</code> checks all fields against their valid ranges. Out-of-range values return <code>UVHTTP_ERROR_INVALID_PARAM</code>.</p></li><li><p><strong>Immutability</strong>: Config should not be modified while the server is listening. Changes take effect on the next listen.</p></li></ol><h2 id="test-requirements" tabindex="-1">Test Requirements <a class="header-anchor" href="#test-requirements" aria-label="Permalink to &quot;Test Requirements&quot;">​</a></h2><ul><li>Config creation with defaults</li><li>Individual field modification</li><li>Validation of valid and invalid values</li><li>Boundary testing (min/max for each field)</li><li>NULL parameter handling</li><li>Config free (no-op on NULL)</li><li>Config set/get on context</li><li>Complete workflow (create, modify, validate, use, free)</li></ul>',20)])])}const h=e(n,[["render",a]]);export{f as __pageData,h as default};
